def make_polynomial(variable, terms):
    return get("make", "polynomial")(variable, terms)



      make_polynomial_example

p1 = make_polynomial("x",
                     llist(make_term(2, make_python_number(4)),
                           make_term(1, make_python_number(3)),
                           make_term(0, make_python_number(7))))
p2 = make_polynomial("x",
                     llist(make_term(2, make_python_number(5)),
                           make_term(1, make_python_number(2)),
                           make_term(0, make_python_number(10))))

print(mul(p1, p2))


